/**
 * lib/invoices/tax/pdf/logo.ts
 *
 * The Arena mark, embedded in the source as a data URI.
 *
 * ── WHY NOT public/arena_logo.png ───────────────────────────────────────────
 * The renderer runs inside an Inngest job on a serverless function, where the
 * public directory is served by the CDN and is not part of the deployed
 * filesystem. Reading it there fails at runtime, and it fails on the one code
 * path nobody watches. A remote URL is worse: an invoice that renders without
 * its letterhead because a fetch timed out is not an invoice anyone wants to
 * receive, and @react-pdf/renderer would swallow it silently.
 *
 * So the bytes travel with the code. Nothing to fetch, nothing to fail.
 *
 * ── HOW IT WAS PREPARED ─────────────────────────────────────────────────────
 * From public/arena_logo.png (1600x536, 654 KB), which is mostly empty plate:
 * cropped to the mark, downscaled to 380x69, and the decorative white specks
 * from the original dark background dropped, since on white paper they print as
 * grey dust. Result is 42 KB, which renders at roughly 230 dpi at the size it
 * is placed. Regenerate the same way if the brand mark changes.
 */

/** PNG with an alpha channel, so it sits on the white page with no plate. */
export const ARENA_LOGO_DATA_URI = "data:image/png;base64,";

/** Intrinsic size, used to keep the aspect ratio honest in the template. */
export const ARENA_LOGO_ASPECT = 380 / 69;
